": "https://openalex.org/W2736977076", "doi": null, "title": "Positioning and Power in Academic Publishing: Players, Agents and Agendas", "publication_year": 2016, "type": "article", "cited_by_count": 1027, "open_access": {"is_oa": true, "oa_status": "green", "oa_url": "https://orca.cardiff.ac.uk/id/eprint/108581/1/9781614996491.pdf", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:https://orca.cardiff.ac.uk:108581", "doi": null, "is_oa": true, "landing_page_url": "https://orca.cardiff.ac.uk/id/eprint/108581/1/9781614996491.pdf", "pdf_url": "https://orca.cardiff.ac.uk/id/eprint/108581/1/9781614996491.pdf", "source": {"id": "https://openalex.org/S4306401195", "display_name": "ORCA Online Research @Cardiff (Cardiff University)", "issn_l": null, "issn": null, "is_oa": false, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I79510175", "host_organization_name": "Cardiff University", "host_organization_lineage": ["https://openalex.org/I79510175"], "host_organization_lineage_names": [], "type": "repository"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "acceptedVersion", "is_accepted": true, "is_published": false, "raw_source_name": null, "raw_type": "PeerReviewed"}, "abstract": "The field of electronic publishing has grown exponentially in the last two decades, but we are still in the middle of this digital transformation. With technologies coming and going for all kinds of reasons, the distribution of economic, technological and discursive power continues to be negotiated. This book presents the proceedings of the 20th Conference on Electronic Publishing (Elpub), held in Göttingen, Germany, in June 2016. This year’s conference explores issues of positioning and power in academic publishing, and it brings together world leading stakeholders such as academics, practitioners, policymakers, students and entrepreneurs from a wide variety of fields to exchange information and discuss the advent of innovations in the areas of electronic publishing, as well as reflect on the development in the field over the last 20 years. Topics covered in the papers include how to maintain the quality of electronic publications, modeling processes and the increasingly prevalent issue of open access, as well as new systems, database repositories and datasets. This overview of the field will be of interest to all those who work in or make use of electronic publishing."}]", "excerpt_truncated": true, "source_sha256": "a46ce5a2c0ed23cd1c4cedbffc86b88eef309625a927ac1b8bcfcd2d56dbdd36", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s10994-025-06955-2", "doi:10.1007/s10994-025-06955-2.pdf", "openalex:W4368755578", "openalex:W2736977076"], "source_candidates": ["https://doi.org/10.1007/s10994-025-06955-2", "https://link.springer.com/content/pdf/10.1007/s10994-025-06955-2.pdf", "https://orca.cardiff.ac.uk/id/eprint/108581/1/9781614996491.pdf"], "source_candidate_identities": {}}
